<template>
  <div class="task-tool">
    <header><div><h3>每日任务</h3><small>{{ today }} · 连续打卡 {{ data.streak }} 天</small></div><button @click="edit()">＋ 新增</button></header>
    <div class="stats"><b>{{ done }}/{{ active.length }}</b><span>完成率 {{ rate }}%</span><button @click="reminders = !reminders">{{ reminders ? '提醒已开启' : '开启提醒' }}</button></div>
    <div class="progress"><i :style="{ width: rate + '%' }"></i></div>
    <EventCountdown />
    <div class="filters"><select v-model="filter"><option value="all">全部任务</option><option value="pending">未完成</option><option value="done">已完成</option><option value="skipped">已跳过</option></select><select v-model="tag"><option value="">全部标签</option><option v-for="item in tags" :key="item">{{ item }}</option></select><select v-model="sort"><option value="priority">按优先级</option><option value="created">按创建时间</option></select></div>
    <p v-if="error" class="error" role="alert">{{ error }} <button @click="load">重试</button></p>
    <div class="list"><p v-if="loading">加载中…</p><p v-else-if="!visible.length">暂无任务，安排一次复盘吧。</p><div v-for="task in visible" :key="task.id" class="row" :class="task.status"><input type="checkbox" :checked="task.status === 'done'" :disabled="busy" :aria-label="'完成'+task.title" @change="state(task, task.status === 'done' ? 'pending' : 'done')" /><button class="copy" @click="edit(task)"><b>{{ task.title }}</b><small v-if="task.description">{{ task.description }}</small><small>{{ task.tag ? '#'+task.tag+' · ' : '' }}{{ task.repeat === 'daily' ? '每日重复' : '当日任务' }} {{ task.reminder }}</small></button><span class="due" :class="dueMeta(task).tone" :title="'到期 ' + task.dueDate">{{ dueMeta(task).text }}</span><span class="priority" :class="task.priority">{{ labels[task.priority] }}</span><button v-if="task.repeat === 'daily'" :disabled="busy" @click="state(task, task.status === 'skipped' ? 'pending' : 'skipped')">{{ task.status === 'skipped' ? '恢复' : '跳过' }}</button><button :disabled="busy" title="删除任务" @click="remove(task)">×</button></div></div>
    <div v-if="upcomingTodos.length" class="upcoming"><p class="up-title">即将到来 · 倒计时</p><div v-for="task in upcomingTodos" :key="'u-' + task.id" class="row upcoming-row"><button class="copy" @click="edit(task)"><b>{{ task.title }}</b><small>{{ task.tag ? '#' + task.tag + ' · ' : '' }}{{ task.repeat === 'daily' ? '每日重复' : '当日任务' }} · 起始 {{ task.dueDate }}</small></button><span class="due" :class="dueMeta(task).tone" :title="'到期 ' + task.dueDate">{{ dueMeta(task).text }}</span></div></div>
    <div class="trend"><div v-for="day in data.history" :key="day.date" :title="day.date+' 完成 '+day.done+'/'+day.total"><b>{{ day.done }}</b><i :style="{ height: Math.max(3, day.total ? day.done/day.total*24 : 0)+'px' }"></i><small>{{ day.date.slice(5) }}</small></div></div><p class="foot">近7天完成趋势 · 提醒仅在网页打开时生效</p>
    <Teleport to="body"><div v-if="editing" class="task-mask" @click.self="editing = false"><form class="task-dialog" @submit.prevent="save"><header><b>{{ draft.id ? '编辑任务' : '新增任务' }}</b><button type="button" @click="editing = false">×</button></header><label>任务名称<input v-model.trim="draft.title" required maxlength="100" /></label><label>描述<textarea v-model="draft.description" maxlength="500" rows="2"></textarea></label><div class="form-grid"><label>截止 / 起始日期<input v-model="draft.dueDate" type="date" required /></label><label>周期<select v-model="draft.repeat"><option value="once">仅指定日期</option><option value="daily">从此日起每日重复</option></select></label><label>优先级<select v-model="draft.priority"><option value="high">高</option><option value="medium">中</option><option value="low">低</option></select></label><label>提醒<input v-model="draft.reminder" type="time" /></label></div><label>自定义标签<input v-model.trim="draft.tag" maxlength="30" placeholder="盯盘 / 学习 / 代码开发" /></label><p v-if="formError" class="error">{{ formError }}</p><button class="submit" :disabled="busy">{{ busy ? '保存中…' : '保存任务' }}</button></form></div><aside v-if="reminderText" class="task-reminder" role="alert"><b>任务提醒</b><p>{{ reminderText }}</p><button @click="reminderText = ''">知道了</button></aside></Teleport>
  </div>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { dailyTaskApi } from '../utils/api'
import EventCountdown from './EventCountdown.vue'
const dayKey = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date())
const today = ref(dayKey()); const data = reactive({ tasks: [], history: [], streak: 0, upcoming: [] }); const draft = reactive({})
const editing = ref(false); const busy = ref(false); const loading = ref(false); const error = ref(''); const formError = ref('')
const filter = ref('all'); const tag = ref(''); const sort = ref('priority'); const reminders = ref(false); const reminderText = ref('')
const notified = new Set(); let timer
const labels = { high: '高', medium: '中', low: '低' }; const priorities = { high: 0, medium: 1, low: 2 }
const active = computed(() => data.tasks.filter(task => task.status !== 'skipped'))
const done = computed(() => active.value.filter(task => task.status === 'done').length)
const rate = computed(() => active.value.length ? Math.round(done.value / active.value.length * 100) : 0)
const tags = computed(() => [...new Set(data.tasks.map(task => task.tag).filter(Boolean))])
const visible = computed(() => data.tasks.filter(task => (filter.value === 'all' || task.status === filter.value) && (!tag.value || task.tag === tag.value)).sort((first, second) => (sort.value === 'priority' ? priorities[first.priority] - priorities[second.priority] : 0) || second.createdAt - first.createdAt))
const failureText = failure => failure.response?.data?.error || failure.message || '操作失败'
const upcomingTodos = computed(() => (data.upcoming || []).filter(task => !tag.value || task.tag === tag.value))
function dueMeta(task) { const days = Math.round((Date.parse(task.dueDate + 'T00:00:00Z') - Date.parse(today.value + 'T00:00:00Z')) / 86400000); if (days > 0) return { text: '还有 ' + days + ' 天', tone: days <= 3 ? 'urgent' : 'future' }; if (task.repeat === 'daily') return { text: '第 ' + (-days + 1) + ' 天', tone: 'run' }; if (days === 0) return { text: '今天', tone: 'now' }; return { text: '已过 ' + -days + ' 天', tone: 'past' } }
async function load() { loading.value = true; error.value = ''; try { today.value = dayKey(); Object.assign(data, await dailyTaskApi.list(today.value)) } catch (failure) { error.value = failureText(failure) } finally { loading.value = false } }
function edit(task) { Object.assign(draft, { id: '', title: '', description: '', dueDate: today.value, priority: 'medium', repeat: 'once', reminder: '', tag: '' }, task || {}); formError.value = ''; editing.value = true }
async function save() { busy.value = true; try { if (draft.id) await dailyTaskApi.update(draft.id, draft); else await dailyTaskApi.create(draft); editing.value = false; await load() } catch (failure) { formError.value = failureText(failure) } finally { busy.value = false } }
async function state(task, status) { if (busy.value) return; busy.value = true; try { await dailyTaskApi.state(task.id, today.value, status); await load() } catch (failure) { error.value = failureText(failure) } finally { busy.value = false } }
async function remove(task) { if (!window.confirm('删除任务及完成记录：'+task.title+'？')) return; busy.value = true; try { await dailyTaskApi.remove(task.id); await load() } catch (failure) { error.value = failureText(failure) } finally { busy.value = false } }
function checkReminders() { if (dayKey() !== today.value) { load(); return } if (!reminders.value) return; const time = new Intl.DateTimeFormat('en-GB', { timeZone: 'Asia/Shanghai', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date()); const due = data.tasks.filter(task => task.status === 'pending' && task.reminder && task.reminder <= time && !notified.has(today.value+task.id)); if (due.length) { due.forEach(task => notified.add(today.value+task.id)); reminderText.value = due.map(task => task.title).join('、') } }
onMounted(() => { load(); timer = setInterval(checkReminders, 30000) })
onBeforeUnmount(() => clearInterval(timer))
</script>
<style scoped>
.task-tool{min-width:0;height:100%;display:flex;flex-direction:column;color:#334762}.task-tool header,.task-dialog header{display:flex;justify-content:space-between;align-items:center;gap:8px}.task-tool h3{font-size:17px;font-weight:700}.task-tool small{font-size:10px;color:#8b9aae}.task-tool button{font-size:11px;color:#687d98}.task-tool header>button{background:#e5edf8;padding:6px 10px;border-radius:8px}.stats{display:flex;align-items:center;gap:10px;margin:14px 0 7px;font-size:11px;color:#8a9aae}.stats b{font-size:25px;color:#527594}.stats button{margin-left:auto}.progress{height:4px;background:#e6ecf2;border-radius:5px;overflow:hidden}.progress i{display:block;height:100%;background:#79a89a}.filters{display:flex;gap:5px;margin:12px 0}.filters select{flex:1;min-width:0;padding:4px;background:#f2f5f8;border:1px solid #dce4ed;border-radius:5px;font-size:10px}.list{flex:1;min-height:80px;max-height:175px;overflow:auto}.list>p{font-size:11px;color:#94a3b8;padding:20px 0;text-align:center}.row{display:flex;align-items:center;gap:7px;padding:7px 0;border-bottom:1px solid #e9edf2}.row input{accent-color:#6d9c8b}.copy{flex:1;min-width:0;text-align:left}.copy b,.copy small{display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.copy b{font-size:12px;color:#415a75}.copy small{margin-top:3px}.row.done b{text-decoration:line-through;color:#98a6b5}.row.skipped{opacity:.5}.priority{font-size:10px;padding:2px 5px;border-radius:4px}.priority.high{background:#f8e5e3;color:#a86c67}.priority.medium{background:#f4eddb;color:#a28b4c}.priority.low{background:#e1eee8;color:#6d9388}.trend{display:flex;gap:8px;height:55px;margin-top:10px}.trend>div{display:flex;flex:1;align-items:center;justify-content:flex-end;flex-direction:column;gap:3px}.trend b,.trend small{font-size:9px;color:#91a1b4}.trend i{width:60%;background:#a0bdb1;border-radius:3px}.foot{font-size:9px;color:#a1adbc;text-align:center;margin-top:5px}.error{color:#bd6966;font-size:11px;margin:7px 0}.task-mask{position:fixed;inset:0;z-index:100;background:#172b4780;display:grid;place-items:center;padding:20px}.task-dialog{width:min(440px,100%);max-height:90vh;overflow:auto;background:white;border-radius:18px;padding:22px;color:#415570;box-shadow:0 20px 60px #17325140}.task-dialog label{display:block;font-size:12px;margin-top:12px}.task-dialog input,.task-dialog textarea,.task-dialog select{width:100%;display:block;margin-top:5px;border:1px solid #dce5ef;border-radius:7px;padding:8px;color:#415570}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 10px}.submit{margin-top:18px;padding:10px;width:100%;border-radius:8px;background:#6087b0;color:white}.task-reminder{position:fixed;z-index:101;right:20px;bottom:25px;padding:20px;background:#fff;border:1px solid #d8e9e3;border-radius:14px;box-shadow:0 8px 30px #213c5c30;color:#415570;max-width:340px}.task-reminder p{font-size:13px;margin:8px 0}.task-tool button:disabled,.task-dialog button:disabled{opacity:.5}
.due{flex:none;font-size:9px;font-weight:600;padding:2px 6px;border-radius:5px;background:#eef2f6;color:#8a9aac;white-space:nowrap;font-variant-numeric:tabular-nums}
.due.future{background:#e6efee;color:#5f8f81}
.due.urgent{background:#f7ecd8;color:#a8812f}
.due.now{background:#f8e3e1;color:#b3564f}
.due.run{background:#e7eef7;color:#5b7ba0}
.due.past{background:#eef1f4;color:#93a1b0}
.upcoming{margin-top:9px;border-top:1px dashed #e2e9f1;padding-top:7px}
.upcoming .up-title{font-size:10px;color:#9aa9b9;margin-bottom:4px}
.upcoming .row{border-bottom:none;padding:5px 0;opacity:.94}
</style>
